        comment=line.strip()
        cur=[line]
    elif cur:
        cur.append(line)
        if line.strip().startswith('},'):
            text=''.join(cur)
            m=re.search(r'/\*\s*(X86_[^,]+),\s*(X86_INS_[^:]+):\s*([^*]+)\*/', text)
            arr=re.search(r'\{([^{}]*)\}\s*\n\}', text)
            # better find last brace line before }
            lines=text.splitlines()
            arrline=[l for l in lines if 'CS_AC' in l or re.search(r'\{\s*0\s*\}', l)]
            if m:
                if arrline:
                    inside=arrline[-1].split('{',1)[1].split('}',1)[0]
                    toks=[t.strip() for t in inside.split(',') if t.strip()]
                    n=0
                    for t in toks:
                        if t=='0': break
                        n+=1
                else: n=None
                entries.append((m.group(1),m.group(2),m.group(3).strip(),n, arrline[-1].strip() if arrline else ''))
            cur=[]
for e in entries[:10]: print(e)
print('entries',len(entries))
# Find instruction comments in X86GenAsmWriter1.inc where print sequence has N printOperand-like calls > n maybe impossible parse all cases.
